mapper.select:
select B.MENU_ID, B.PARENT_ID, B.NAME, B.ENAME,B.TYPE, B.MENU_SEQ, B.JS_EVENT, B.URL, B.IS_DISPLAY, B.IS_DISABLED, ifnull(B.PERMS,'') as PERMS, B.IS_CHECK, B.SPARE2,B.SPARE1, B.URL_TYPE, B.ICON,B.IMAGE_PATH, B.PRIORITY, B.CREATE_TIME
from SYS_MENU B
WHERE 1=1  AND B.TYPE = 'WORK' AND B.DEL_FLAG = 0


        AND B.APP_ID = #{currAppId}


        AND NAME like concat('%', #{menuName}, '%')


        AND IS_DISPLAY = #{visible}


        AND IS_DISABLED = #{status}


order by PARENT_ID, PRIORITY

select B.MENU_ID, B.PARENT_ID, B.NAME, B.ENAME,B.TYPE, B.MENU_SEQ, B.JS_EVENT, B.URL, B.IS_DISPLAY, B.IS_DISABLED, ifnull(B.PERMS,'') as PERMS, B.IS_CHECK, B.SPARE2,B.SPARE1, B.URL_TYPE, B.ICON,B.DEL_FLAG, B.PRIORITY, B.CREATE_TIME
, (select COUNT(MENU_ID) from SYS_MENU where PARENT_ID = B.MENU_ID AND DEL_FLAG = 0) CHILD_NUM
from SYS_MENU B
WHERE 1=1  AND B.TYPE = 'WORK'

    AND B.APP_ID = #{currAppId}



        AND B.DEL_FLAG = #{delFlag}


        AND B.DEL_FLAG = 0



    AND B.URL_TYPE = #{menuType}



        AND NAME like concat('%', #{menuName}, '%')


        AND IS_DISPLAY = #{visible}


        AND IS_DISABLED = #{status}






                AND ( B.PARENT_ID = 0 OR B.PARENT_ID IS NULL )


                and B.PARENT_ID = #{parentId}




        AND (B.PARENT_ID = 0 OR B.PARENT_ID IS NULL)



    AND  (B.NAME like concat(concat('%',#{q}),'%')
    or B.ENAME like concat(concat('%',#{q}),'%')
    or B.MENU_SEQ like concat(concat('%',#{q}),'%')
    )

order by PARENT_ID, PRIORITY

select distinct B.MENU_ID, B.PARENT_ID, B.NAME,B.TYPE, B.ENAME, B.MENU_SEQ, B.JS_EVENT, B.URL, B.IS_DISPLAY, B.IS_DISABLED, ifnull(B.PERMS,'') as PERMS, B.IS_CHECK, B.SPARE2,B.SPARE1, B.URL_TYPE, B.ICON, B.PRIORITY, B.CREATE_TIME from SYS_MENU B where B.URL_TYPE in ('CATAGORY', 'MENU') and B.IS_DISABLED = 0 AND B.TYPE = 'WORK' AND B.DEL_FLAG = 0
AND B.APP_ID = #{currAppId}
order by B.PARENT_ID, B.PRIORITY

select distinct B.MENU_ID, B.PARENT_ID, B.NAME,B.TYPE, B.ENAME, B.MENU_SEQ, B.JS_EVENT, B.URL, B.IS_DISPLAY, B.IS_DISABLED, ifnull(B.PERMS,'') as PERMS, B.IS_CHECK, B.SPARE2,B.SPARE1, B.URL_TYPE, B.ICON, B.PRIORITY, B.CREATE_TIME from SYS_MENU B left join SYS_ROLE_MENU SRM on B.MENU_ID = SRM.MENU_ID left join SYS_ROLE RO on SRM.ROLE_ID = RO.ROLE_ID left join PUBLIC_GROUP pg on RO.ROLE_ID = pg.ROLE_ID left join USER_RANGE_ORGAN uro on uro.GROUP_ID = pg.GROUP_ID where uro.USERL_ID = #{memberId} and uro.IS_MEMBER = 1 AND B.TYPE = 'WORK' AND B.DEL_FLAG = 0
AND B.APP_ID = #{currAppId}
AND B.NAME like concat('%', #{menuName}, '%')
AND B.IS_DISPLAY = #{visible}
AND B.IS_DISABLED = #{status}
order by B.PARENT_ID, B.PRIORITY

select distinct B.MENU_ID, B.PARENT_ID, B.NAME,B.TYPE, B.ENAME, B.MENU_SEQ, B.JS_EVENT, B.URL, B.IS_DISPLAY, B.IS_DISABLED, ifnull(B.PERMS,'') as PERMS, B.IS_CHECK, B.SPARE2,B.SPARE1, B.URL_TYPE, B.ICON, B.PRIORITY, B.CREATE_TIME from SYS_MENU B left join SYS_ROLE_MENU SRM on B.MENU_ID = SRM.MENU_ID left join SYS_ROLE RO on SRM.ROLE_ID = RO.ROLE_ID left join PUBLIC_GROUP pg on RO.ROLE_ID = pg.ROLE_ID left join USER_RANGE_ORGAN uro on uro.GROUP_ID = pg.GROUP_ID where uro.USERL_ID = #{memberId} and uro.IS_MEMBER = 1 AND B.URL_TYPE in ('CATAGORY', 'MENU') and B.IS_DISABLED = 0 AND RO.STATUS = 0 AND B.TYPE = 'WORK' AND B.DEL_FLAG = 0
AND B.APP_ID = #{currAppId}
order by B.PARENT_ID, B.PRIORITY

select distinct B.PERMS
from SYS_MENU B
left join SYS_ROLE_MENU SRM on B.MENU_ID = SRM.MENU_ID
where B.IS_DISABLED = 0 AND B.TYPE = 'WORK' AND B.DEL_FLAG = 0 and SRM.ROLE_ID = #{roleId}

    AND B.APP_ID = #{currAppId}

select distinct B.CODE
from SYS_ROLE B
left join PUBLIC_GROUP pg on B.ROLE_ID = pg.ROLE_ID
left join USER_RANGE_ORGAN uro on uro.GROUP_ID = pg.GROUP_ID
WHERE B.STATUS = 1 and uro.IS_MEMBER = 1 and uro.USERL_ID = #{memberId}

    AND B.APP_ID = #{currAppId}

select distinct B.ROLE_ID
from SYS_ROLE B
left join PUBLIC_GROUP pg on B.ROLE_ID = pg.ROLE_ID
left join USER_RANGE_ORGAN uro on uro.GROUP_ID = pg.GROUP_ID
WHERE B.STATUS = 1 and uro.IS_MEMBER = 1 and uro.USERL_ID = #{memberId}

    AND B.APP_ID = #{currAppId}

SELECT DISTINCT B.RELATION_ID,B.ORGAN_ID,B.GROUP_ID,B.POSITION_ID
,B.USER_ID, B.USERL_ID AS MEMBER_ID,tm.NICK_NAME,bu.MOBILE
FROM USER_RANGE_ORGAN B
LEFT JOIN BASE_USER bu ON B.USER_ID = bu.USER_ID
LEFT JOIN BASE_USER_EXT bue ON B.USER_ID = bue.USER_ID
LEFT JOIN THIRD_MEMBER tm ON B.USER_ID = tm.USER_ID
WHERE B.DEL_FLAG = 0

    AND B.TYPE = #{type}


    AND B.ORGAN_ID = #{organId}


    AND B.GROUP_ID = #{groupId}


    AND B.POSITION_ID = #{positionId}


    AND B.USER_ID = #{userId}

SELECT B.ORGAN_ID,B.POSITION_ID,B.USER_ID,B.TYPE
FROM USER_RANGE_ORGAN B
WHERE 1=1

    AND B.TYPE = #{type}


    AND B.USER_ID = #{userId}


    AND B.POSITION_ID = #{positionId}


    AND B.ORGAN_ID = #{organId}


    AND B.FOREIGN_ID = #{areaId}

mapper.delete:
delete from USER_RANGE_ORGAN where GROUP_ID = #{groupId} and
USERL_ID IN

    #{id}

mapper.update:
UPDATE USER_RANGE_ORGAN B SET B.DEL_FLAG = 1 where EXISTS ( SELECT 1 FROM ( SELECT S.CONN_USER_ID FROM MATERIAL_PEOPLE_BASE S WHERE S.CONN_USER_ID IN
#{id}
)C WHERE C.CONN_USER_ID = B.USER_ID ) AND TYPE = 10 AND B.DEL_FLAG = 0

mapper.select:
select bu.* from BASE_USER bu
LEFT JOIN USER_RANGE_ORGAN uro on uro.USER_ID = bu.USER_ID
where 1=1

    AND uro.ORGAN_ID=#{organId}


    AND uro.FOREIGN_ID=#{areaId}


    and uro.POSITION_ID =#{positionId}


    and uro.GROUP_ID= #{groupId}

AND bu.CREATE_TYPE=10
and uro.DEL_FLAG=0

select count(uro.GROUP_ID) from USER_RANGE_ORGAN uro
left join THIRD_MEMBER tm on tm.MEMBER_ID=uro.USERL_ID
where tm.USER_ID =#{userId}
  and uro.GROUP_ID = #{groupId}

select count(uro.GROUP_ID) from USER_RANGE_ORGAN uro
where uro.USERL_ID =#{memberId}
  and uro.GROUP_ID = #{groupId}

select count(uro.GROUP_ID) from USER_RANGE_ORGAN uro
left join BASE_USER bu on bu.USER_ID=uro.USER_ID
where bu.mobile =#{mobile}
  and uro.GROUP_ID = #{groupId}

select count(uro.GROUP_ID) from USER_RANGE_ORGAN uro
left join THIRD_MEMBER tm on tm.MEMBER_ID=uro.USERL_ID
left join BASE_USER bu on bu.USER_ID=tm.USER_ID
where bu.mobile =#{mobile}
  and uro.GROUP_ID = #{groupId}
  and uro.ORGAN_ID=#{organId}
